from __future__ import annotations

import hashlib
import json
from pathlib import Path
import subprocess
from typing import Any, Iterator

ROOT = Path.cwd().resolve()
WORK = ROOT/'_scratch/cleanup-control-X8B6'
PATH = 'docs/examples/mac-cleanup.lo'


def walk(node: Any) -> Iterator[dict[str, Any]]:
    if isinstance(node, dict):
        yield node
        for key, child in node.items():
            if key != 'span':yield from walk(child)
    elif isinstance(node, list):
        for child in node:yield from walk(child)


def clean(node: Any) -> Any:
    if isinstance(node, dict):return {key:clean(value) for key,value in node.items() if key!='span'}
    if isinstance(node, list):return [clean(value) for value in node]
    return node


def scalar_free_bytes(node: Any) -> Any:
    if isinstance(node,dict):
        if node.get('kind')=='projection' and node.get('parts')==['before','free_bytes']:
            return {'kind':'reference','name':'free_bytes'}
        return {key:scalar_free_bytes(value) for key,value in node.items()}
    if isinstance(node,list):return [scalar_free_bytes(value) for value in node]
    return node


def calls(node: Any) -> set[str]:
    return {item['name'] for item in walk(node) if item.get('kind') in ('call','pipe')}


before = json.loads((WORK/'before-parse.stdout.json').read_text())['program']
parsed = subprocess.run([str(ROOT/'bin/lo'),'parse',PATH,'--format','json'],cwd=ROOT,capture_output=True,check=False)
(WORK/'after-parse.stdout.json').write_bytes(parsed.stdout)
(WORK/'after-parse.stderr.json').write_bytes(parsed.stderr)
assert parsed.returncode==0,parsed.stderr.decode()
after = json.loads(parsed.stdout)['program']
oldflows = {flow['name']:flow for flow in before['statements'] if flow['kind']=='flow'}
newflows = {flow['name']:flow for flow in after['statements'] if flow['kind']=='flow'}
assert len(newflows)==301
assert len(newflows)==len([flow for flow in after['statements'] if flow['kind']=='flow'])
assert not {'Flow.select','Flow.capture'}&calls(after)
manifest = json.loads((WORK/'control-transform.json').read_text())
checked_branches=0
for name,old in oldflows.items():
    new=newflows[name]
    assert clean(old['parameters'])==clean(new['parameters']),name
    assert clean(old['output'])==clean(new['output']),name
    oldcalls=[item for item in walk(old['body']) if item.get('kind')=='call' and item.get('name')=='Flow.select']
    entries=[item for item in manifest['choices'] if item['flow']==name]
    assert len(oldcalls)==len(entries),name
    for oldcall,entry in zip(oldcalls,entries,strict=True):
        number=entry['choice']
        selector=next(item for item in new['body'] if item.get('name')==f'selector_{number}')
        assert clean(selector['value'])==clean(oldcall['arguments'][0]['value']),name
        choice=next(item for item in new['body'] if item.get('name')==f'choice_{number}')['value']
        args=oldcall['arguments']
        originals=[args[index]['value'] for index in range(2,len(args)-1,2)]+[args[-1]['value']]
        for branch_index,(arm,original,record) in enumerate(zip(choice['cases'],originals,entry['branches'],strict=True),1):
            assert arm['body']['text']==str(branch_index),name
            if branch_index<len(originals):assert clean(arm['head'])==clean(args[2*branch_index-1]['value']),name
            else:assert arm['kind']=='default',name
            helper=newflows[record['callback']]
            body=clean(helper['body'][0]['value'])
            expected=clean(original)
            if name=='Started':expected=scalar_free_bytes(expected)
            assert body==expected,(name,record['callback'])
            fold=next(item for item in new['body'] if item.get('name')==f'choice_{number}_result_{branch_index}')['value']
            assert fold['name']=='Flow.fold'
            actual=[item['value'] for item in fold['arguments']]
            filtered=actual[0]
            assert filtered['name']=='List.filter'
            assert filtered['arguments'][0]['value']['name']=='List.new'
            assert filtered['arguments'][0]['value']['arguments'][0]['value']['name']==f'choice_{number}'
            assert filtered['arguments'][1]['value']['text']==str(branch_index)
            assert filtered['arguments'][2]['value']['name']=='SelectedChoice'
            context=record['context']
            if name=='Started':context=['free_bytes' if value=='before' else value for value in context]
            assert [item['name'] for item in actual[2:-1]]==context
            assert all(item['kind']=='reference' for item in actual[2:])
            assert actual[-1]['name']==record['callback']
            assert [item['name'] for item in helper['parameters'][:-2]]==context
            assert helper['parameters'][-2]['name']=='previous' and helper['parameters'][-1]['name']=='selected'
            if branch_index>1:assert actual[1]['name']==f'choice_{number}_result_{branch_index-1}'
            checked_branches+=1

for flow in newflows.values():
    names=[param['name'] for param in flow['parameters']]+[item['name'] for item in flow['body'] if item['kind']=='binding']
    assert len(names)==len(set(names)),('duplicate-local',flow['name'])
    assert flow['body'][-1]['kind']=='return'
    assert sum(item['kind']=='return' for item in flow['body'])==1

edges={name:set() for name in newflows}
direct=set()
for name,flow in newflows.items():
    for node in walk(flow['body']):
        if node.get('kind')=='commit':direct.add(name)
        if node.get('kind') in ('call','pipe') and node['name'] in newflows:edges[name].add(node['name'])
        if node.get('kind')=='reference' and node['name'] in newflows:edges[name].add(node['name'])
visited=set()
active=set()
def visit(name: str) -> None:
    assert name not in active,('cycle',name)
    if name in visited:return
    active.add(name)
    for child in edges[name]:visit(child)
    active.remove(name);visited.add(name)
for name in edges:visit(name)
committing=set(direct)
while True:
    updated=committing|{name for name,children in edges.items() if children&committing}
    if updated==committing:break
    committing=updated
